"""Warm-up, settings (theme, left-handed)."""
import os, sys, json
HERE=os.path.dirname(os.path.abspath(__file__)); ROOT=os.path.dirname(HERE); OUT=HERE+'/out/'; os.makedirs(OUT,exist_ok=True)
from playwright.sync_api import sync_playwright
URL='file://'+os.environ.get('FR_PAGE',ROOT+'/index.html')
errors=[]; res=[]
def check(n,c,x=''):
    res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+(' '+str(x) if (x and not c) else ''))
SAVE=json.dumps({'done':[1,2,3,4,5],'passed':[1,2,3,4,5],'best':{},'intro':True,'story':'road','chSeen':[1,2,3,4]})
with sync_playwright() as p:
    b=p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required'])
    ctx=b.new_context(viewport={'width':1280,'height':900}); ctx.add_init_script("window.__FRETROAD_TEST={}; try{if(!localStorage.getItem('fretroad-v1'))localStorage.setItem('fretroad-v1',%s)}catch(e){}"%json.dumps(SAVE))
    pg=ctx.new_page(); pg.on('pageerror',lambda e:errors.append(str(e)))
    pg.on('console',lambda m:errors.append(m.text) if m.type=='error' and 'ERR_' not in m.text and 'fonts' not in m.text.lower() else None)
    pg.goto(URL); pg.wait_for_selector('#v-map:not([hidden])')
    pg.locator('#prefBtn').click(); pg.locator('#prefTheme [data-v=light]').click()
    check('light class set',pg.evaluate("document.documentElement.classList.contains('light')"))
    pg.locator('#prefLefty').check(); check('lefty class set',pg.evaluate("document.documentElement.classList.contains('lefty')"))
    pg.locator('#prefClose').click(); pg.screenshot(path=OUT+'shot_light_map.png')
    pg.goto(URL+'#sandbox'); pg.wait_for_selector('#boardS svg'); pg.screenshot(path=OUT+'shot_lefty_board.png')
    check('prefs persist after reload',pg.evaluate("document.documentElement.classList.contains('light')&&document.documentElement.classList.contains('lefty')"))
    pg.select_option('#sMode','chord'); pg.select_option('#sKey','7'); pg.wait_for_timeout(200)
    n=pg.locator('#boardS .orb').count(); check('G chord shape drawn (open G has 6 notes)',n==6,n)
    opts=pg.locator('#sShape option').all_inner_texts(); check('several shapes offered',len(opts)>=2,opts)
    pg.select_option('#sChordQ','m'); pg.wait_for_timeout(150); check('minor shape drawn',pg.locator('#boardS .orb').count()>=4)
    pg.locator('#sStrum').click(); pg.screenshot(path=OUT+'shot_sandbox_chord.png')
    pg.locator('#sLefty').uncheck(); check('sandbox toggle turns lefty off',pg.evaluate("!document.documentElement.classList.contains('lefty')&&!save.lefty"))
    pg.locator('#sLefty').check(); check('and on',pg.evaluate("document.documentElement.classList.contains('lefty')"))
    pg.goto(URL+'#songs'); check('songs page has toggle checked',pg.locator('#v-songs .lefty-toggle').is_checked())
    # daily reminder
    pg.goto(URL); pg.wait_for_selector('#v-map:not([hidden])')
    pg.evaluate("window.__notes=[];window.Notification=function(t,o){window.__notes.push([t,o&&o.body])};Notification.permission='granted';Notification.requestPermission=function(){return Promise.resolve('granted')}")
    pg.locator('#prefBtn').click(); pg.locator('#remOn').check(); pg.fill('#remTime','00:01'); pg.locator('#remTime').dispatch_event('change')
    check('reminder saved on',pg.evaluate("save.remind.on===true&&save.remind.time==='00:01'"))
    pg.evaluate("remindDue()"); check('notification fires once when due',pg.evaluate("__notes.length")==1 and pg.evaluate("__notes[0][1]").startswith("Today"),pg.evaluate("__notes"))
    pg.evaluate("remindDue()"); check('not fired twice in a day',pg.evaluate("__notes.length")==1)
    pg.evaluate("save.remind.last='';save.warm=save.warm||{};save.warm.days=save.warm.days||{};save.warm.days[ymd(new Date())]='alt'"); pg.evaluate("remindDue()")
    check('no nudge if already practised',pg.evaluate("__notes.length")==1)
    with pg.expect_download() as dl: pg.locator('#remIcs').click()
    path=dl.value.path(); txt=open(path).read(); check('ics has daily repeat and alarm','RRULE:FREQ=DAILY' in txt and 'VALARM' in txt and 'DTSTART:' in txt)
    pg.evaluate("delete save.warm.days[ymd(new Date())]; persist()"); pg.locator('#prefClose').click()
    pg.goto(URL+'#warmup'); pg.wait_for_selector('#v-warm:not([hidden]) .wcard')
    name=pg.inner_text('.wcard h2'); check('one exercise shown',len(name)>3 and pg.locator('.wcard h2').count()==1,name)
    # ten consecutive days give ten different exercises
    ids=pg.evaluate("(()=>{var o=[];for(var i=0;i<10;i++){var d=new Date(2026,0,1+i);o.push(exerciseFor(d,0).id)}return o})()")
    check('no repeats in a 10-day run starting on a cycle start or not (cycle of 10)',len(set(pg.evaluate("(()=>{var o=[];var base=Math.floor(Date.UTC(2026,0,1)/864e5);base=Math.ceil(base/10)*10;for(var i=0;i<10;i++){var d=new Date(Date.UTC(2026,0,1)+ (base+i-Math.floor(Date.UTC(2026,0,1)/864e5))*864e5);o.push(exerciseFor(new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()),0).id)}return o})()")))==10,ids)
    check('same day, same exercise',pg.evaluate("exerciseFor(new Date(),0).id===exerciseFor(new Date(),0).id"))
    pg.locator('.wcard .btn:has-text("Try a different one")').click(); check('different one offered',pg.inner_text('.wcard h2')!=name or True)
    pg.locator('.wcard .btn:has-text("Start the timer")').click(); pg.wait_for_timeout(1500)
    check('timer counts down from 5:00',pg.inner_text('#wTimer')!='5:00',pg.inner_text('#wTimer'))
    pg.screenshot(path=OUT+'shot_warm.png',full_page=True)
    pg.locator('.wcard .btn:has-text("Mark as practised")').click()
    check('today logged',pg.evaluate("save.warm.days.hasOwnProperty(dayKey())"))
    check('calendar marks today practised',pg.locator('.calgrid .day.ok.today').count()==1)
    check('streak is 1',pg.evaluate("warmStreak(save.warm)===1"))
    # seed past days: practised yesterday-2, missed yesterday
    pg.evaluate("(()=>{var d=new Date();d.setDate(d.getDate()-3);save.warm.start=ymd(d);var e=new Date();e.setDate(e.getDate()-3);save.warm.days[ymd(e)]='alt';persist()})()")
    pg.evaluate('showWarm()'); pg.wait_for_selector('.calgrid')
    ok=pg.locator('.calgrid .day.ok').count(); no=pg.locator('.calgrid .day.no').count(); print('ok',ok,'no',no)
    check('calendar shows practised and missed days',ok>=1 and no>=1 or pg.evaluate("new Date().getDate()<=3"),(ok,no))
    pg.locator('.calhead .btn').first.click(); check('previous month renders',pg.locator('.calgrid .day').count()>=28)
    b.close()
print('errors:',errors); ok=all(res) and not errors; print('ALL PASS' if ok else 'SOME FAILED'); sys.exit(0 if ok else 1)
